CREATE TABLE webhook_deliveries (id TEXT PRIMARY KEY, webhook_endpoint_id TEXT NOT NULL REFERENCES webhook_endpoints(id), event_type TEXT NOT NULL, payload JSONB NOT NULL, state TEXT NOT NULL DEFAULT 'pending', attempt_count INT NOT NULL DEFAULT 0, next_retry_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), last_http_status INT, last_error TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (state IN ('pending','delivered','failed'))); CREATE INDEX idx_webhook_deliveries_retry ON webhook_deliveries(state, next_retry_at) WHERE state = 'pending';
